public class WhileBasicDemo {
    public static void main(String[] args) {
        int i = 1;              // 初始化：循环变量从 1 开始
        while (i <= 5) {        // 条件：只要不超过 5 就继续
            System.out.print(i + " ");
            i++;                // 迭代：每次加 1，保证最终能退出
        }
        System.out.println();
    }
}
