```java
public class ReturnValueDemo {
    public static void main(String[] args) {
        System.out.println("查找结果：" + findFirstEven(new int[]{1, 3, 5, 6, 7, 8}));
        System.out.println("查找结果：" + findFirstEven(new int[]{1, 3, 5, 7}));
    }

    // 返回数组中第一个偶数，找不到返回 -1
    static int findFirstEven(int[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] % 2 == 0) {
                return arr[i];      // 找到就立即返回，后面的元素不再检查
            }
        }
        return -1;                   // 循环结束仍未找到
    }
}
